WITH flattened AS (SELECT id, service, host, level, latency_ms, key, v FROM app_logs LATERAL VIEW EXPLODE(context) t AS key, v) SELECT CASE WHEN latency_ms >= 2320 THEN 'HIGH' ELSE 'LOW' END AS latency_ms_tier, host, SIZE(COLLECT_SET(service)) AS num_services, COUNT(*) AS event_count, ROUND(AVG(latency_ms), 2) AS avg_latency_ms FROM flattened GROUP BY CASE WHEN latency_ms >= 2320 THEN 'HIGH' ELSE 'LOW' END, host;
